<script setup>
import { computed } from 'vue'
const props = defineProps({ ticket: { type: Object, required: true }, reserved: Boolean })
defineEmits(['reserve'])
const price = computed(() => props.ticket.actualValue ? `¥${(props.ticket.actualValue / 100).toFixed(0)}` : '免费')
</script>
<template><article class="ticket-card"><div class="ticket-heading"><span v-if="ticket.type===1">限量预约</span><span v-else>活动凭证</span><strong>{{ price }}</strong></div><h3>{{ ticket.title }}</h3><p>{{ ticket.subTitle || ticket.rules || '预约后请按活动时间到场。' }}</p><div class="ticket-foot"><small v-if="ticket.stock !== null && ticket.stock !== undefined">剩余 {{ ticket.stock }} 个名额</small><small v-else>名额有限，请尽早预约</small><el-button type="primary" :disabled="reserved || ticket.stock===0" @click="$emit('reserve', ticket)">{{ reserved ? '已预约' : ticket.stock===0 ? '名额已满' : '预约参加' }}</el-button></div></article></template>
<style scoped>.ticket-card { padding:var(--space-5); border:1px solid var(--color-border); border-radius:var(--radius-lg); background:var(--color-surface); box-shadow:var(--shadow-sm); }.ticket-heading,.ticket-foot { display:flex; align-items:center; justify-content:space-between; gap:var(--space-3); }.ticket-heading span { padding:4px 8px; border-radius:999px; color:var(--color-accent); background:var(--color-accent-soft); font-size:.75rem; font-weight:700; }.ticket-heading strong { color:var(--color-primary); font-size:1.25rem; }.ticket-card h3 { margin:var(--space-4) 0 var(--space-2); font-size:1.08rem; }.ticket-card p { min-height:42px; margin:0 0 var(--space-5); color:var(--color-text-secondary); font-size:.88rem; }.ticket-foot { padding-top:var(--space-4); border-top:1px solid var(--color-border); }.ticket-foot small { color:var(--color-text-muted); }</style>
